CREATE TABLE ticket(id BIGINT AUTO_INCREMENT PRIMARY KEY,ticket_no VARCHAR(32) NOT NULL UNIQUE,title VARCHAR(128) NOT NULL,description CLOB NOT NULL,priority VARCHAR(16) NOT NULL,status VARCHAR(32) NOT NULL,creator_id BIGINT NOT NULL,assignee_id BIGINT,version INT DEFAULT 0,create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,update_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,deleted TINYINT DEFAULT 0);
CREATE TABLE ticket_comment(id BIGINT AUTO_INCREMENT PRIMARY KEY,ticket_id BIGINT,user_id BIGINT,content VARCHAR(2000),create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,update_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,deleted TINYINT DEFAULT 0);
CREATE TABLE ticket_history(id BIGINT AUTO_INCREMENT PRIMARY KEY,ticket_id BIGINT,operator_id BIGINT,operation_type VARCHAR(32),from_status VARCHAR(32),to_status VARCHAR(32),remark VARCHAR(512),create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE event_outbox(id BIGINT AUTO_INCREMENT PRIMARY KEY,event_id VARCHAR(36),aggregate_type VARCHAR(64),aggregate_id BIGINT,event_type VARCHAR(128),payload CLOB,status VARCHAR(16),retry_count INT,next_retry_time TIMESTAMP,create_time TIMESTAMP,update_time TIMESTAMP);
ALTER TABLE ticket ADD COLUMN affected_ci_code VARCHAR(64);
ALTER TABLE ticket ADD COLUMN source_type VARCHAR(32) DEFAULT 'MANUAL';
ALTER TABLE ticket ADD COLUMN environment VARCHAR(16) DEFAULT 'CORE';
ALTER TABLE ticket ADD COLUMN owner_actor_id BIGINT;
ALTER TABLE ticket ADD COLUMN incident_id VARCHAR(128);
ALTER TABLE ticket ADD COLUMN episode_id VARCHAR(64);
ALTER TABLE ticket ADD COLUMN public_demo TINYINT DEFAULT 0;
